            .params
            .into_iter()
            .map(|(k, v)| json_to_kv_value(&k, v).map(|value| (k, value)))
            .collect::<Result<Vec<_>, _>>()?;
        Ok(Self { tool: w.tool, params, reason: w.reason })
    }
}

