impl From<std::borrow::Cow<'_, str>> for Value {
    fn from(s: std::borrow::Cow<'_, str>) -> Self {
        Self::Str(CompactString::new(s))
    }
}

impl From<i32> for Value {
    fn from(n: i32) -> Self {
        Self::Int(i64::from(n))
    }
}

impl From<u32> for Value {
    fn from(n: u32) -> Self {
        Self::Int(i64::from(n))
    }
}

impl From<i64> for Value {
    fn from(n: i64) -> Self {
        Self::Int(n)
    }
}

impl From<u64> for Value {
    /// [`Value::Int`] when the value fits in `i64`, otherwise [`Value::UInt`]: IDs, hashes and counters keep their
    /// exact digits and render as unquoted numbers, never clamped, rounded or truncated.
    fn from(n: u64) -> Self {
        i64::try_from(n).map_or(Self::UInt(n), Self::Int)
    }
}

impl From<usize> for Value {
    /// Same contract as `From<u64>`.
    fn from(n: usize) -> Self {
        match (i64::try_from(n), u64::try_from(n)) {
            (Ok(i), _) => Self::Int(i),
            (Err(_), Ok(u)) => Self::UInt(u),
            // Not reachable on any platform Rust supports (usize is at most 64 bits); keeps the exact digits.
            (Err(_), Err(_)) => Self::Str(compact_str::format_compact!("{n}")),
        }
    }
}

impl From<f32> for Value {
    /// Keeps the f32's own shortest digits: `0.1f32` becomes `0.1`, not its exact widened value
    /// `0.10000000149011612`. The f32 is printed with its shortest round-trip form and that decimal is read back as
    /// an f64.
    fn from(f: f32) -> Self {
        if !f.is_finite() {
            return Self::Float(f64::from(f));
        }
        let mut digits = String::with_capacity(16);
        let _ = std::fmt::Write::write_fmt(&mut digits, format_args!("{f}"));
        Self::Float(digits.parse().unwrap_or(f64::from(f)))
    }
}

impl From<f64> for Value {
    fn from(f: f64) -> Self {
        Self::Float(f)
    }
}

impl From<bool> for Value {
    fn from(b: bool) -> Self {
        Self::Bool(b)
    }
}

impl From<Option<String>> for Value {
    fn from(s: Option<String>) -> Self {
        match s {
            Some(s) => Self::Str(CompactString::new(s)),
            None => Self::Null,
        }
    }
}

impl std::fmt::Display for Value {
    /// The value's content without TOON quoting: strings verbatim, numbers in TOON canonical form (§2), `null` for
    /// `Null` and for non-finite floats (§3).
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Str(s) => f.write_str(s),
            Self::Int(n) => write!(f, "{n}"),
            Self::UInt(n) => write!(f, "{n}"),
            Self::Float(fl) => {
                let mut s = String::with_capacity(24);
                push_f64(&mut s, *fl);
                f.write_str(&s)
            }
            Self::Bool(b) => f.write_str(if *b { "true" } else { "false" }),
            Self::Null => f.write_str("null"),
        }
    }
}

/// Root-object keys michi composes next to a TOON list (`totalCount`, `help`, `recovery`), which a type name therefore
/// must not take: TOON 4.4 §14.3 forbids duplicate sibling keys.
pub(crate) const RESERVED_TYPE_NAMES: [&str; 3] = crate::kv::RESERVED_ROOT_KEYS;

/// Append one row cell: §7.2 quoting for strings, §2/§3 canonical numbers, the `null` literal. Only strings are
/// truncated to `max_cell_len` chars, counted before escaping, with the caller's `hint` (empty: none) in the suffix.
fn push_cell(out: &mut String, cell: &Value, max_cell_len: usize, hint: &crate::truncate::InlineHint<'_>) {
    use std::fmt::Write as _;
    match cell {
        Value::Str(s) => {
            if s.len() <= max_cell_len {
                out.push_str(&escape_value(s));
            } else {
                let truncated = hint.truncate(s, max_cell_len);
                out.push_str(&escape_value(&truncated));
            }
        }
        Value::Int(n) => {
            let _ = write!(out, "{n}");
        }
        Value::UInt(n) => {
            let _ = write!(out, "{n}");
        }
        Value::Float(f) => push_f64(out, *f),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Null => out.push_str("null"),
    }
}

/// Append the list entry in the form TOON 4.4 prescribes for its shape, each line ending in a newline:
/// - no rows: `key: []` (§9.1; the field list is not emitted, an empty array has no shape),
/// - rows with zero fields: `key[N]:` and N bare `-` items, since empty objects may not use tabular form
///   (§9.3, §9.4, §10),
/// - otherwise the tabular form `key[N]{f1,f2}:` with one row per line at depth 1 (§9.3).
fn push_list(out: &mut String, opts: &crate::toon::ToonOptions) {
    use std::fmt::Write as _;
    out.push_str(&escape_key(&opts.type_name));
    if opts.rows.is_empty() {
        out.push_str(": []\n");
        return;
    }
    let _ = write!(out, "[{}]", opts.rows.len());
    if opts.fields.is_empty() {
        out.push_str(":\n");
        for _ in &opts.rows {
            out.push_str("  -\n");
        }
        return;
    }
    out.push('{');
    for (i, field) in opts.fields.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str(&escape_key(field));
    }
    out.push_str("}:\n");
    // Measured once per document, not once per truncated cell.
    let hint = crate::truncate::InlineHint::new(opts.truncation_hint.as_deref().unwrap_or(""));
    for row in &opts.rows {
        out.push_str("  ");
        for (i, cell) in row.iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            push_cell(out, cell, opts.max_cell_len, &hint);
        }
        out.push('\n');
    }
}

/// Owns [`ToonDocument`] in a module of its own -- containing nothing else
/// -- so the invariant "only `validate` can produce one" is enforced by
/// Rust's own field-privacy rule, not by scanning source text for known
/// bypass shapes. `opts` is visible only inside this module and its
/// descendants; since this module declares no descendants and nothing
/// besides `validate`/`render`, no code anywhere else in this crate --
/// regardless of what shape it takes (a free function, a second impl
/// block, a `From`/`TryFrom` impl, a type alias, or a module gated behind
/// an unanticipated `#[cfg(...)]`) -- can write the struct-literal
/// `ToonDocument { opts }` and have it compile. This module is `mod`, not
/// `pub`, so external code cannot even name `render::proof::ToonDocument`
/// directly; the type is reachable only through the `pub use` re-export
/// below.
///
/// This guarantee holds only GIVEN two preconditions that Rust's type
/// system does not itself enforce, and that are each pinned by a
/// dedicated assertion in `sole_constructor_for_toon_document` rather than
/// left as a precondition nothing verifies: (1) `opts` stays genuinely
/// bare-private -- widening its visibility to reach the rest of this
/// module is a one-token, entirely ordinary-looking edit that would grant
/// field access to all of `render.rs` and let a constructor live outside
/// `proof` entirely, defeating the guarantee above while every OTHER
/// check here stays green; and (2) `proof`'s true extent is what the
/// scanning code believes it is -- found, historically, to be defeatable
/// by a multi-line string literal (e.g. inside a `#[doc = "..."]`
/// attribute) containing a bare `}`, which an earlier, purely line-based
/// brace-matcher mistook for the module's real close. `find_closing_line`
/// now tracks actual lexical structure (string and char literals,
/// comments) rather than taking for granted that a closing brace is
/// always alone on its rustfmt-normalized line, closing that specific
/// hole; a companion assertion additionally pins the literal line
/// immediately following `proof`'s close, as
/// defense in depth against a future defect in that scan.
///
/// **Known, accepted residual:** none of the above closes a bypass hidden
/// behind `macro_rules!` expansion -- a `some_macro!();` item-position
/// invocation inside this module's own `impl` block is, after expansion,
/// code that genuinely lives inside `proof` and therefore has real field
/// access, the same way `validate` does. No text scan can see through
/// macro expansion (`include_str!`, which every guard test here reads
/// from, captures source as written, before expansion), so this is a
/// limit of the mechanism, not a missed pattern. Per this invariant's own
/// design record, the property being enforced is that a maintainer
/// *following this codebase's patterns* cannot reintroduce the defect by
/// accident; a maintainer deliberately writing macro-hidden field access
/// to evade this exact module boundary is choosing to defeat it, not
/// accidentally tripping over it, and is outside what a source-level
/// guard can mechanically prevent. Closing that residual for real would
/// mean asserting over post-expansion, cfg-resolved output (e.g. via
/// `cargo-expand`) rather than unexpanded source text -- a deliberate
/// scope decision, not an oversight.
mod proof {
    /// Proof that a `ToonOptions` value has passed structural validation.
    ///
    /// The only function that produces a `ToonDocument` is
    /// [`ToonDocument::validate`] -- see this module's own doc comment for
    /// why no other function anywhere in the crate can construct one.
    /// Borrows `&'a ToonOptions` immutably, so the validated options cannot
    /// be mutated while the proof is live.
    #[derive(Debug)]
    pub struct ToonDocument<'a> {
        opts: &'a crate::toon::ToonOptions,
    }

    impl<'a> ToonDocument<'a> {
        /// Validate `opts` and return a proof it satisfies every structural
        /// invariant [`ToonDocument::render`] depends on.
        ///
        /// Every type name and field name is encodable (TOON 4.4 §7.3 quotes
        /// the ones that need it), so validation only rejects options that
        /// would make the document itself invalid TOON.
        ///
        /// # Errors
        ///
        /// Checks run in this order and the first failure is returned:
        /// [`crate::toon::ToonError::InvalidTypeName`] if `type_name` is a
        /// reserved root key (`totalCount`, `help` or `recovery`),
        /// [`crate::toon::ToonError::TooManyFields`] past
        /// [`crate::toon::MAX_FIELDS`] fields,
        /// [`crate::toon::ToonError::InvalidFieldName`] if a field name appears
        /// more than once, [`crate::toon::ToonError::TooManyCells`] if
        /// `rows × fields` is past [`crate::toon::MAX_CELLS`],
        /// [`crate::toon::ToonError::TruncationHintTooLong`] if the truncation
        /// hint is past [`crate::toon::MAX_TRUNCATION_HINT_CHARS`] chars, and
        /// [`crate::toon::ToonError::RowLengthMismatch`] if any row's length
        /// differs from `fields.len()`. Every check is linear in the input.
        pub fn validate(opts: &'a crate::toon::ToonOptions) -> Result<Self, crate::toon::ToonError> {
            use crate::toon::{ToonError, MAX_CELLS, MAX_FIELDS, MAX_TRUNCATION_HINT_CHARS};
            if super::RESERVED_TYPE_NAMES.contains(&opts.type_name.as_str()) {
                return Err(ToonError::InvalidTypeName { name: opts.type_name.clone() });
            }
            if opts.fields.len() > MAX_FIELDS {
                return Err(ToonError::TooManyFields { count: opts.fields.len(), max: MAX_FIELDS });
            }
            let mut seen = std::collections::HashSet::with_capacity(opts.fields.len());
            for field in &opts.fields {
                if !seen.insert(field.as_str()) {
                    return Err(ToonError::InvalidFieldName { name: field.clone() });
                }
            }
            if opts.rows.len().saturating_mul(opts.fields.len()) > MAX_CELLS {
                return Err(ToonError::TooManyCells {
                    rows: opts.rows.len(),
                    fields: opts.fields.len(),
                    max: MAX_CELLS,
                });

use crate::hints::Hint;
use crate::kv::KvItem;
use crate::recovery::RecoveryHint;
use crate::toon::Value;

/// The serialisation format for `AgentResponse::render`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
#[non_exhaustive]
pub enum OutputFormat {
    /// Plain-text TOON / kv format. Default.
    #[default]
    Text,
    /// Compact JSON object.
    Json,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum RenderTarget {
    Unset,
    Toon,
    Kv,
}

/// Default per-cell truncation limit used by [`AgentResponse::new`].
pub const DEFAULT_TRUNCATE_CELLS: usize = 200;

/// Builder for an agent-facing response.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct AgentResponse {
    /// The TOON list slot: type name, fields, rows, total count, cell cap and truncation hint, kept as the options
    /// the renderer validates and renders by reference, so a render never copies the rows. Its `hints` stay empty:
    /// the response's hints are appended after the body instead.
    toon: crate::toon::ToonOptions,
    target: RenderTarget,
    single_item: Vec<KvItem>,
    hints: Vec<Hint>,
    recovery: Vec<RecoveryHint>,
    is_error: bool,
    human_content: Option<String>,
}

impl AgentResponse {
    /// Create a new, empty response for the given type name.
    pub fn new(type_name: impl Into<String>) -> Self {
        Self {
            toon: crate::toon::ToonOptions::new(type_name, Vec::new(), Vec::new()).max_cell_len(DEFAULT_TRUNCATE_CELLS),
            target: RenderTarget::Unset,
            single_item: Vec::new(),
            hints: Vec::new(),
            recovery: Vec::new(),
            is_error: false,
            human_content: None,
        }
    }

    /// Populate the TOON list path.
    #[must_use]
    pub fn items(mut self, rows: Vec<Vec<Value>>, fields: &[&str]) -> Self {
        self.toon.rows = rows;
        self.toon.fields = fields.iter().map(|s| (*s).to_string()).collect();
        self.target = RenderTarget::Toon;
        self
    }

    /// Set the total available count.
    #[must_use]
    pub fn total_count(mut self, n: usize) -> Self {
        self.toon.total_count = Some(n);
        self
    }

    /// Report a list cut in one call: sets the total count to `outcome.total_before` and, only when something was
    /// cut, appends [`TruncationOutcome::hint`](crate::truncation::TruncationOutcome::hint)`(guidance)`, so the
    /// `totalCount` and the `help[]` line always describe the same cut.
    ///
    /// It does not set the rows: the response holds TOON [`Value`] rows, not the caller's `T`, so pass `outcome.kept`
    /// (converted to rows) to [`items`](Self::items) yourself. Later [`total_count`](Self::total_count) or
    /// [`hints`](Self::hints) calls still override what this sets.
    ///
    /// ```
    /// use michi_core::toon::Value;
    /// use michi_core::{truncate_by_count, AgentResponse, OutputFormat};
    ///
    /// let outcome = truncate_by_count(vec![1, 2, 3, 4], 2);
    /// let rows = outcome.kept.iter().map(|n| vec![Value::Int(*n)]).collect();
    /// let r = AgentResponse::new("issues").items(rows, &["n"]).truncation(&outcome, "pass --limit 4");
    /// assert_eq!(
    ///     r.render(OutputFormat::Text),
    ///     "issues[2]{n}:\n  1\n  2\ntotalCount: 4\nhelp[1]: showing 2 of 4; pass --limit 4"
    /// );
    /// ```
    #[must_use]
    pub fn truncation<T>(
        mut self,
        outcome: &crate::truncation::TruncationOutcome<T>,
        guidance: impl Into<String>,
    ) -> Self {
        self.toon.total_count = Some(outcome.total_before);
        if let Some(hint) = outcome.hint(guidance) {
            self.hints.push(hint);
        }
        self
    }

    /// Populate the KV single-item path.
    #[must_use]
    pub fn kv_items(mut self, items: Vec<KvItem>) -> Self {
        self.single_item = items;
        self.target = RenderTarget::Kv;
        self
    }

    /// Append a contextual hint.
    #[must_use]
    pub fn hint(mut self, hint: impl Into<String>) -> Self {
        self.hints.push(Hint::new(hint));
        self
    }

    /// Replace all contextual hints.
    #[must_use]
    pub fn hints(mut self, hints: Vec<Hint>) -> Self {
        self.hints = hints;
        self
    }

    /// Append a recovery hint.
    #[must_use]
    pub fn recovery_hint(mut self, r: RecoveryHint) -> Self {
        self.recovery.push(r);
        self
    }

    /// Set the max string cell length, in chars, before inline truncation on the TOON path. Default:
    /// [`DEFAULT_TRUNCATE_CELLS`].
    ///
    /// The limit counts characters before TOON escaping and quoting, so a cell that needs quotes or escapes is
    /// written longer than `limit` (see [`crate::toon::ToonOptions::max_cell_len`]). The KV path is never truncated.
    #[must_use]
    pub fn truncate_cells_at(mut self, limit: usize) -> Self {
        self.toon.max_cell_len = limit;
        self
    }

    /// Set the caller's instruction for getting a truncated TOON cell in full, appended to the truncation suffix as
    /// `" — use {hint}"` (see [`crate::toon::ToonOptions::truncation_hint`]). Unset by default: the suffix then only
    /// reports how many chars were cut, since michi never invents a parameter the tool may not have.
    #[must_use]
    pub fn truncation_hint(mut self, hint: impl Into<String>) -> Self {
        self.toon.truncation_hint = Some(hint.into());
        self
    }

    /// Mark this response as an error state.
    #[must_use]
    pub fn as_error(mut self) -> Self {
        self.is_error = true;
        self
    }

    /// Attach a human-facing companion block (`audience: user`).
    #[must_use]
    pub fn human_content(mut self, text: impl Into<String>) -> Self {
        self.human_content = Some(text.into());
        self
    }

    /// The TOON body, and whether it is a validation-failure error block instead of the requested rows.
    fn toon_body(&self) -> (String, bool) {
        match self.toon.validate() {
            Ok(doc) => (doc.render(), false),
            Err(e) => (validation_error_body("toon_validation_failed", &e.to_string()), true),
        }
    }

    /// The KV body, and whether it is a validation-failure error block instead of the requested items (a duplicate
    /// or reserved key, see [`crate::kv::KvError`]).
    fn kv_body(&self) -> (String, bool) {
        // `render_kv` renders nothing for no items, dropping the count; a response that set one still reports it,
        // as the TOON path does (`t: []\ntotalCount: 0`).
        if self.single_item.is_empty() {
            let body = self.toon.total_count.map_or_else(String::new, |n| format!("totalCount: {n}"));
            return (body, false);
        }
        match crate::kv::render_kv(&self.single_item, self.toon.total_count, &[]) {
            Ok(body) => (body, false),
            Err(e) => (validation_error_body("kv_validation_failed", &e.to_string()), true),
        }
    }

    /// The selected body, and whether this response is an error: set by `as_error()` or by a body that failed
    /// validation. Every output surface reads its error flag from here so text, JSON and MCP never disagree.
    fn body(&self) -> (String, bool) {
        let (body, failed) = match self.target {
            RenderTarget::Toon | RenderTarget::Unset => self.toon_body(),
            RenderTarget::Kv => self.kv_body(),
        };
        (body, failed || self.is_error)
    }

    /// Compose the text document: body, help block, recovery block. Each part is a TOON 4.4 document without a
    /// trailing newline and the append helpers join them with one LF, so the result is one root object whose keys
    /// are unique (the body cannot use `totalCount`, `help` or `recovery`). Appends to `body` in place.
    fn finish_text(&self, mut body: String) -> String {
        if !self.hints.is_empty() || !self.recovery.is_empty() {
            body.reserve(1 + self.hints.len() * 60 + self.recovery.len() * 80);
        }
        crate::hints::append_hints(&mut body, &self.hints);
        crate::recovery::append_recovery(&mut body, &self.recovery);
        body
    }

    /// Render the response in the requested format.
    #[must_use]
    pub fn render(&self, format: OutputFormat) -> String {
        match format {
            OutputFormat::Text => self.render_text(),
            OutputFormat::Json => self.render_json(),
        }
    }

    /// Render via the TOON path.
    #[must_use]
    pub fn render_toon(&self) -> String {
        self.finish_text(self.toon_body().0)
    }

    /// Render via the KV path.
    #[must_use]
    pub fn render_kv(&self) -> String {
        self.finish_text(self.kv_body().0)
    }

    fn render_text(&self) -> String {
        self.finish_text(self.body().0)
    }

    /// Whether this response is an error: `as_error()` was called, or the TOON rows or KV items failed validation and
    /// the body is a `toon_validation_failed` or `kv_validation_failed` error block. Validates without rendering.
    #[must_use]
    pub fn is_error(&self) -> bool {
        self.is_error
            || match self.target {
                RenderTarget::Toon | RenderTarget::Unset => self.toon.validate().is_err(),
                RenderTarget::Kv => crate::kv::validate_keys(&self.single_item).is_err(),
            }
    }

    /// Render just the `help[N]:` block for `self.hints`.
    #[must_use]
    pub fn render_hints_only(&self) -> String {
        crate::hints::render_hints(&self.hints)
    }

    /// Render for the given audience.
    #[must_use]
    pub fn render_for(&self, audience: crate::audience::Audience) -> String {
        match audience {
            crate::audience::Audience::Assistant => self.render_text(),
            crate::audience::Audience::User => self.human_content.clone().unwrap_or_else(|| self.render_text()),
        }
    }

    /// Whether `.human_content()` was set on this builder.
    #[must_use]
    pub fn has_human_content(&self) -> bool {
        self.human_content.is_some()
    }

    /// Build the MCP `CallToolResult` for this response.
    #[must_use]
    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
        let (body, is_error) = self.body();
        let structured_content = self.json_from_body(&body, is_error);
        let mut content = vec![crate::mcp::ContentBlock {
            text: self.finish_text(body),
            audience: vec![crate::audience::Audience::Assistant],
        }];
        if let Some(human) = &self.human_content {
            content.push(crate::mcp::ContentBlock {
                text: human.clone(),
                audience: vec![crate::audience::Audience::User],
            });
        }
        crate::mcp::CallToolResult { content, is_error, structured_content }
    }

    fn render_json(&self) -> String {
        let (body, is_error) = self.body();
        self.json_from_body(&body, is_error)
    }

    fn json_from_body(&self, body: &str, is_error: bool) -> String {
        let capacity = body.len()
            + self.hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>()
            + self.recovery.len() * 64
            + 64;
        let mut out = String::with_capacity(capacity);
        out.push_str("{\"body\":");
        json_string(&mut out, body);
        out.push_str(",\"hints\":[");
        for (i, h) in self.hints.iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            json_string(&mut out, h.as_str());
        }
        out.push_str("],\"recovery\":[");
        for (i, r) in self.recovery.iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            out.push_str("{\"tool\":");
            json_string(&mut out, &r.tool);
            out.push_str(",\"params\":");
            crate::recovery::push_params_json(&mut out, &r.params);
            if let Some(reason) = &r.reason {
                out.push_str(",\"reason\":");
                json_string(&mut out, reason);
            }
            out.push('}');
        }
        out.push_str("],\"isError\":");
        out.push_str(if is_error { "true" } else { "false" });
        out.push('}');
        out
    }
}

/// The body that replaces rows or items that cannot form a valid document: `error: <code>` and the quoted message.
fn validation_error_body(code: &str, message: &str) -> String {
    let message = crate::toon::escape_value(message);
    let mut out = String::with_capacity(17 + code.len() + message.len());
    out.push_str("error: ");
    out.push_str(code);
    out.push_str("\nmessage: ");
    out.push_str(&message);
    out
}

fn json_string(out: &mut String, s: &str) {
    crate::kv::json_escape_str(out, s);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn capacity_violations_are_toon_validation_errors_on_every_surface() {
        let fields: Vec<String> = (0..=crate::toon::MAX_FIELDS).map(|i| format!("f{i}")).collect();
        let field_refs: Vec<&str> = fields.iter().map(String::as_str).collect();
        let too_wide = AgentResponse::new("t").items(vec![], &field_refs);
        let long_hint = AgentResponse::new("t")
            .items(vec![vec![Value::from("x")]], &["a"])
            .truncation_hint("h".repeat(crate::toon::MAX_TRUNCATION_HINT_CHARS + 1));
        for (r, message) in [
            (too_wide, "fields length 1001 exceeds maximum of 1000"),
            (long_hint, "truncation_hint length 257 chars exceeds maximum of 256"),
        ] {
            assert!(r.is_error(), "{message}");
            let text = r.render(OutputFormat::Text);
            assert_eq!(text, format!("error: toon_validation_failed\nmessage: {message}"));
            assert!(r.render(OutputFormat::Json).contains("\"isError\":true"), "{message}");
            let result = r.to_call_tool_result();
            assert!(result.is_error, "{message}");
            assert_eq!(result.content[0].text, text);
            assert!(result.structured_content.contains("\"isError\":true"), "{message}");
        }
    }

