    /// ends with `" ({removed} more chars)"`, plus `" — use {hint}"` when [`Self::truncation_hint`] is set, or with
    /// `…` when the cap is too small for that suffix; see [`crate::truncate::truncate()`].
    pub max_cell_len: usize,
