    pub key: String,
    /// The component's actual value.
    pub value: KvValue,
    /// Optional health signal; `None` renders health and reason as `null`.
    pub health: Option<Health>,
}

impl StatusItem {
    /// A status item with no health signal.
    #[must_use]
    pub fn new(key: impl Into<String>, value: KvValue) -> Self {
