154	pub fn render_recovery(hints: &[RecoveryHint]) -> String {
155	    if hints.is_empty() {
156	        return String::new();
157	    }
158	    let capacity = 40 + hints.len() * 60;
159	    let mut out = String::with_capacity(capacity);
160	    append_recovery(&mut out, hints);
