167	/// one, and nothing follows the block. Does nothing for an empty slice.
168	pub fn append_recovery(out: &mut String, hints: &[RecoveryHint]) {
169	    if hints.is_empty() {
170	        return;
171	    }
172	    crate::hints::start_block(out);
173	    out.push_str("recovery[");
174	    out.push_str(&hints.len().to_string());
175	    out.push_str("]{tool,params,reason}:");
176	    for hint in hints {
177	        out.push_str("\n  ");
178	        out.push_str(&crate::toon::escape_value(&hint.tool));
179	        out.push(',');
180	        out.push_str(&crate::toon::escape_value(&params_json(&hint.params)));
181	        out.push(',');
182	        match &hint.reason {
