189	/// The parameters as a compact JSON object, written by the same writer as the JSON companions.
190	pub(crate) fn params_json(params: &[(String, KvValue)]) -> String {
191	    let mut json = String::with_capacity(2 + params.iter().map(|(k, _)| k.len() + 16).sum::<usize>());
