196	/// Append the parameters as a compact JSON object. A repeated key is written once, at its first position, with its
197	/// last value -- what [`RecoveryHint::param`] would have produced -- so the object never holds a duplicate key.
198	pub(crate) fn push_params_json(out: &mut String, params: &[(String, KvValue)]) {
199	    out.push('{');
200	    let mut first = true;
201	    for (i, (k, _)) in params.iter().enumerate() {
202	        if params[..i].iter().any(|(earlier, _)| earlier == k) {
203	            continue;
204	        }
205	        let Some((_, v)) = params[i..].iter().rev().find(|(later, _)| later == k) else { continue };
206	        if !first {
207	            out.push(',');
208	        }
209	        first = false;
210	        crate::kv::json_escape_str(out, k);
211	        out.push(':');
212	        crate::kv::kv_value_to_json(out, v);
213	    }
214	    out.push('}');
215	}
